  assign cnt_dec_bits = FEC_Decoder_Wrapper_cnt_dec_bits;

  assign cnt_bist_start = FEC_Decoder_Wrapper_cnt_bist_start;

  assign cap_in = FEC_Decoder_Wrapper_cap_in;

  assign cap_deint = FEC_Decoder_Wrapper_cap_deint;

  assign cap_out = FEC_Decoder_Wrapper_cap_out;

  FecCaptureCadence u_FecCaptureCadence (.clk(clk),
                                                          .reset(reset),
                                                          .enb_1_2_0(enb_1_2_0),
                                                          .startIn(QPSK_Demodulator_startOut),
                                                          .validIn(QPSK_Demodulator_validOut),
                                                          .capCad(capCad)  // uint32
                                                          );

  assign cap_cad = capCad;

  RstCsCounter u_RstCsCounter (.clk(clk),
                                                .reset(reset),
                                                .enb_1_2_0(enb_1_2_0),
                                                .e(Frequency_and_Time_Synchronizer_rstcsDet),
                                                .c(c)  // uint32
                                                );

  assign rstcs_count = c;

  assign CfcEstSI_out1 = {{11{normCoarseFreqEst[20]}}, normCoarseFreqEst};

  always @(posedge clk or posedge reset)
    begin : CfcEstReg_process
      if (reset == 1'b1) begin
        CfcEstReg_out1 <= 32'b00000000000000000000000000000000;
      end
      else begin
        if (enb_1_2_0) begin
          CfcEstReg_out1 <= CfcEstSI_out1;
        end
      end
    end

  assign cfc_est = CfcEstReg_out1;

  assign fs_runmax = Frequency_and_Time_Synchronizer_fs_runmax;

  assign BoDtc1_out1 = {15'b0, QPSK_Demodulator_dataOut};

  assign BoDtc2_out1 = {15'b0, QPSK_Demodulator_startOut};

  assign BoDtc3_out1 = {15'b0, QPSK_Demodulator_validOut};

  assign QPSK_Demodulator_beatobsDecis[0] = QPSK_Demodulator_beatobsDecis_0;
  assign QPSK_Demodulator_beatobsDecis[1] = QPSK_Demodulator_beatobsDecis_1;


  genvar ii;
  generate
    for(ii = 32'sd0; ii <= 32'sd1; ii = ii + 32'sd1) begin:BoDtc4_out1_gen
      assign BoDtc4_out1[ii] = {15'b0, QPSK_Demodulator_beatobsDecis[ii]};
    end
  endgenerate

  assign BoDtc5_out1 = {8'b0, Frequency_and_Time_Synchronizer_beatobsRhCtr};

  assign BoDtc6_out1 = {11'b0, Frequency_and_Time_Synchronizer_beatobsPush};

  assign BoDtc7_out1 = {11'b0, Frequency_and_Time_Synchronizer_beatobsPop};

  BeatObs u_BeatObs (.dOut(BoDtc1_out1),  // uint16
                                      .sOut(BoDtc2_out1),  // uint16
                                      .vOut(BoDtc3_out1),  // uint16
                                      .decis_0(BoDtc4_out1[0]),  // uint16
                                      .decis_1(BoDtc4_out1[1]),  // uint16
                                      .rhc(BoDtc5_out1),  // uint16
                                      .pushc(BoDtc6_out1),  // uint16
                                      .popc(BoDtc7_out1),  // uint16
                                      .dbgI1(dbgI1),  // uint16
                                      .dbgQ1(dbgQ1)  // uint16
                                      );

  assign BoOutDtcI_out1 = dbgI1;

  assign beatobsI1 = BoOutDtcI_out1;

  assign BoOutDtcQ_out1 = dbgQ1;

  assign beatobsQ1 = BoOutDtcQ_out1;

  // 2026-08-29: 0x20C/0x210 re-purposed as the beat witness read-back (the BfContract viol counters were
  // miswired per KNOWN_HOLES H-11 and unused). witA = {2'b0, numEntries, push-pop delta, 2'b0};
  // witB = {push_on_full_count[31:16], delta_change_count[15:0]}.
  assign beatfix_viol_count = pdWitA;

  assign beatfix_viol_latch = pdWitB;

endmodule  // QPSK_Rx

